//! 卡片容器 — generated by `lyco new` (template `container`).
//! Behavior lives here; styling + [meta] live in `assets/components/卡片容器.toml`.

use ply_engine::prelude::*;

use crate::components::config::{self, 卡片容器Config};
use crate::theme;

fn cfg() -> 卡片容器Config {
    config::effective(
        config::Style::current().卡片容器,
        卡片容器Config::get(),
        卡片容器Config::merged,
    )
}

/// A 卡片容器 component.
pub fn 卡片容器(ui: &mut Ui<'_, ()>, inner: impl FnOnce(&mut Ui<'_, ()>)) {
    let c = cfg();
    let theme = theme::theme();
    ui.element()
        .width(fit!())
        .height(fit!())
        .background_color(c.background.map(Color::from).unwrap_or(theme.colors.surface_container.into()))
        .corner_radius(c.radius.unwrap_or(theme.shapes.radius_md))
        .layout(|l| l.padding(c.pad_x.unwrap_or(theme::px(16.0)) as u16))
        .children(inner);
}
